export const title = "How to Check Whether Replacement Casters Fit Your Office Chair";
export const metaTitle = "How to Check Whether Replacement Casters Fit";
export const metaDescription = "Identify the chair model and approved replacement options, then confirm the original caster connection and dimensions using the manufacturer's.";
